<?php // phpcs:ignore WordPress.Files.FileName -- Composer PSR-4 class/file mapping; see docs/CODING-STANDARDS.md.
/**
 * JSXGraph reconstruction proposals of the figures in an import review: propose, accept, reject.
 *
 * @package OhMyLMS
 */

namespace OhMyLMS\ExamImport;

defined( 'ABSPATH' ) || exit;

/**
 * A figure placement in a review row can carry one `proposal`: a declarative JSXGraph spec
 * ({@see FigureSpec}, never code) generated by the configured exam converter or written by the
 * reviewer, with a status (`proposed`, `accepted`, `rejected`), its origin (`generated`, `authored`,
 * `edited`) and, once accepted, whether it replaces the original crop for learners or sits beside it.
 *
 * Only these operations change what learners see: accepting copies the spec into the placement and
 * selects `jsxgraph` (replace) or `both` (accompany); rejecting returns to the original. Every change
 * clears the figure's approval and returns the row to "needs review", so a person approves exactly
 * what is delivered. All writes go through {@see Review::write()} (job lock, revision, review state).
 */
final class Proposals {

	/**
	 * Propose a reconstruction: generated by the configured converter, or written by the reviewer.
	 * A new proposal replaces the previous one.
	 *
	 * @param int        $id        Job ID.
	 * @param int        $index     Row index.
	 * @param string     $figure_id Placement ID.
	 * @param int        $revision  Draft revision.
	 * @param string     $source    generate|authored.
	 * @param mixed|null $spec      Declarative spec, for `authored`.
	 * @return array|\WP_Error Job detail view.
	 */
	public static function propose( $id, $index, $figure_id, $revision, $source, $spec = null ) {
		$origin = 'authored';
		if ( 'generate' === $source ) {
			if ( ! \OhMyLMS\AI\Settings::configured( 'exam_converter' ) ) {
				return new \WP_Error( 'ohmylms_exam_import_converter_unavailable', __( 'Generating a reconstruction needs the exam converter in Settings › AI tools. You can write the configuration instead.', 'ohmylms' ), array( 'status' => 409 ) );
			}
			$job    = Review::job( $id );
			$row    = $job['draft'][ $index ] ?? null;
			$figure = $row ? self::find( (array) ( $row['figures'] ?? array() ), $figure_id ) : null;
			if ( ! $job || 'ready_for_review' !== $job['state'] || (int) ( $job['draft_revision'] ?? 0 ) !== (int) $revision || ! $figure ) {
				// Let the write below report the precise conflict, state or missing figure.
				$spec = null;
			} else {
				if ( ! Review::owns_asset( $id, (string) $figure['asset_id'] ) ) {
					return self::forbidden();
				}
				$context = implode( "\n", array_merge( array( (string) $row['question'] ), array_map( 'strval', array_column( (array) $row['parts'], 'prompt' ) ) ) );
				$spec    = Reconstruction::propose( $id, (string) $figure['asset_id'], mb_substr( $context, 0, 20000 ) );
				if ( is_wp_error( $spec ) ) {
					return self::unusable( $spec );
				}
			}
			$origin = 'generated';
		}
		return Review::write(
			$id,
			$index,
			$revision,
			static function ( array &$job, $index ) use ( $id, $figure_id, $spec, $origin ) {
				return self::change(
					$job,
					$index,
					$figure_id,
					static function ( array $figure ) use ( $id, $spec, $origin ) {
						if ( ! Review::owns_asset( $id, (string) $figure['asset_id'] ) ) {
							return self::forbidden();
						}
						$asset = Figures::asset( (string) $figure['asset_id'] );
						if ( ! $asset || 'ready' !== $asset['state'] ) {
							return new \WP_Error( 'ohmylms_exam_import_figure_unavailable', __( 'Wait until the crop is ready before proposing a reconstruction.', 'ohmylms' ), array( 'status' => 409 ) );
						}
						$valid = FigureSpec::validate( $spec );
						if ( is_wp_error( $valid ) ) {
							return self::unusable( $valid );
						}
						$before = $figure['proposal'] ?? null;
						// Changing a generated proposal by hand makes it an edited one.
						$edited             = 'authored' === $origin && in_array( $before['origin'] ?? '', array( 'generated', 'edited' ), true );
						$figure['proposal'] = array(
							'status'  => 'proposed',
							'origin'  => $edited ? 'edited' : $origin,
							'display' => $before['display'] ?? 'replace',
							'spec'    => $valid,
						);
						// A new proposal is not delivered until it is accepted again.
						$figure['selected'] = 'original';
						unset( $figure['spec'] );
						return $figure;
					}
				);
			}
		);
	}

	/**
	 * Accept the proposal: learners see the reconstruction instead of, or beside, the original.
	 *
	 * @param int    $id        Job ID.
	 * @param int    $index     Row index.
	 * @param string $figure_id Placement ID.
	 * @param int    $revision  Draft revision.
	 * @param string $display   replace|accompany.
	 * @return array|\WP_Error Job detail view.
	 */
	public static function accept( $id, $index, $figure_id, $revision, $display ) {
		return Review::write(
			$id,
			$index,
			$revision,
			static function ( array &$job, $index ) use ( $figure_id, $display ) {
				return self::change(
					$job,
					$index,
					$figure_id,
					static function ( array $figure ) use ( $display ) {
						if ( empty( $figure['proposal'] ) ) {
							return self::missing();
						}
						$figure['proposal']['status']  = 'accepted';
						$figure['proposal']['display'] = $display;
						$figure['spec']                = $figure['proposal']['spec'];
						$figure['selected']            = 'accompany' === $display ? 'both' : 'jsxgraph';
						return $figure;
					}
				);
			}
		);
	}

	/**
	 * Reject the proposal: learners see the original crop. The proposal is kept for reference.
	 *
	 * @param int    $id        Job ID.
	 * @param int    $index     Row index.
	 * @param string $figure_id Placement ID.
	 * @param int    $revision  Draft revision.
	 * @return array|\WP_Error Job detail view.
	 */
	public static function reject( $id, $index, $figure_id, $revision ) {
		return Review::write(
			$id,
			$index,
			$revision,
			static function ( array &$job, $index ) use ( $figure_id ) {
				return self::change(
					$job,
					$index,
					$figure_id,
					static function ( array $figure ) {
						if ( empty( $figure['proposal'] ) ) {
							return self::missing();
						}
						$figure['proposal']['status'] = 'rejected';
						$figure['selected']           = 'original';
						unset( $figure['spec'] );
						return $figure;
					}
				);
			}
		);
	}

	/**
	 * Apply a change to one placement, then validate the row as a row edit does.
	 *
	 * @param array    $job       Job state (by reference).
	 * @param int      $index     Row index.
	 * @param string   $figure_id Placement ID.
	 * @param callable $change    Receives the placement; returns it changed, or a WP_Error.
	 * @return true|\WP_Error
	 */
	private static function change( array &$job, $index, $figure_id, callable $change ) {
		$rows    = $job['draft'];
		$figures = (array) ( $rows[ $index ]['figures'] ?? array() );
		foreach ( $figures as $at => $figure ) {
			if ( (string) ( $figure['id'] ?? '' ) !== (string) $figure_id ) {
				continue;
			}
			$changed = $change( $figure );
			if ( is_wp_error( $changed ) ) {
				return $changed;
			}
			$changed['approved']        = false;
			$figures[ $at ]             = $changed;
			$rows[ $index ]['figures']  = $figures;
			$rows[ $index ]['reviewed'] = false;
			$inventory                  = $job['draft_inventory'] ?? $job['inventory'];
			$clean                      = Extraction::questions( $rows, $inventory['question_numbers'], $inventory['page_count'] );
			if ( is_wp_error( $clean ) ) {
				return self::unusable( $clean );
			}
			$job['draft']    = $clean;
			$job['rejected'] = array_values( array_diff( Review::rejected( $job ), array( (string) $clean[ $index ]['number'] ) ) );
			return true;
		}
		return new \WP_Error( 'ohmylms_exam_import_figure_not_found', __( 'This question has no such figure.', 'ohmylms' ), array( 'status' => 404 ) );
	}

	/**
	 * One placement by ID.
	 *
	 * @param array  $figures   Placements.
	 * @param string $figure_id ID.
	 * @return array|null
	 */
	private static function find( array $figures, $figure_id ) {
		foreach ( $figures as $figure ) {
			if ( is_array( $figure ) && (string) ( $figure['id'] ?? '' ) === (string) $figure_id ) {
				return $figure;
			}
		}
		return null;
	}

	/**
	 * A spec or provider reply that cannot be used, as a 422 with the cause.
	 *
	 * @param \WP_Error $error Cause.
	 * @return \WP_Error
	 */
	private static function unusable( \WP_Error $error ) {
		$status = (int) ( $error->get_error_data()['status'] ?? 422 );
		return new \WP_Error(
			'exam_figure_spec' === $error->get_error_code() ? 'ohmylms_exam_import_invalid_proposal' : $error->get_error_code(),
			$error->get_error_message(),
			array(
				'status' => 'exam_figure_spec' === $error->get_error_code() || $status < 400 ? 422 : $status,
				'reason' => $error->get_error_code(),
			)
		);
	}

	/**
	 * No proposal to decide on.
	 *
	 * @return \WP_Error
	 */
	private static function missing() {
		return new \WP_Error( 'ohmylms_exam_import_no_proposal', __( 'This figure has no reconstruction proposal yet.', 'ohmylms' ), array( 'status' => 409 ) );
	}

	/**
	 * Foreign crop.
	 *
	 * @return \WP_Error
	 */
	private static function forbidden() {
		return new \WP_Error( 'ohmylms_exam_import_figure_forbidden', __( 'A figure belongs to another import.', 'ohmylms' ), array( 'status' => 403 ) );
	}
}
